import{_ as t,H as p,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"开篇词 | 漫游未来，一起开启AI大模型系统修炼之旅","description":"","frontmatter":{},"headers":[{"level":2,"title":"AI 系统很难，我能学会吗？","slug":"ai-系统很难-我能学会吗","link":"#ai-系统很难-我能学会吗","children":[]},{"level":2,"title":"这门课程能让你获得什么呢？","slug":"这门课程能让你获得什么呢","link":"#这门课程能让你获得什么呢","children":[]},{"level":2,"title":"结语","slug":"结语","link":"#结语","children":[]}],"relativePath":"AI大模型系统实战/开篇词｜漫游未来，一起开启AI大模型系统修炼之旅.md","filePath":"AI大模型系统实战/开篇词｜漫游未来，一起开启AI大模型系统修炼之旅.md","lastUpdated":1795452834000}'),A={name:"AI大模型系统实战/开篇词｜漫游未来，一起开启AI大模型系统修炼之旅.md"};function l(n,e,s,E,r,I){return p(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="开篇词-漫游未来-一起开启ai大模型系统修炼之旅" tabindex="-1">开篇词 | 漫游未来，一起开启AI大模型系统修炼之旅 <a class="header-anchor" href="#开篇词-漫游未来-一起开启ai大模型系统修炼之旅" aria-label="Permalink to &quot;开篇词 | 漫游未来，一起开启AI大模型系统修炼之旅&quot;">​</a></h1><p>你好，我是 Tyler。欢迎加入我的专栏，跟我一起学习 AI 大模型系统实战课。</p><p>先来做一个自我介绍。我曾是亚马逊的 Applied Scientist，负责数据算法相关的工作，拥有十余年的多模态大模型、推荐系统和分布式机器学习的经验。因此，在 AI 大模型兴起之后，我自然地开始负责 AI 大模型系统相关的工作。现在，我是国内某大厂 AIGC 团队的算法负责人。</p><p>近年来，我也一直在主管团队的培训和面试工作，因此，我对国内外科技公司，在 AI 人才招聘时考察的重点，还有同学们在职业发展过程中所产生的困惑都深有感触。在与刚刚踏入 AI方向的同学交流时，我经常发现大家都有一个感觉，那就是 AI 系统永远学不完，学不会。</p><p>所以如果你也深陷这种迷茫之中，请不要焦虑，因为这非常正常。学习 AI 系统需要具备机器学习、分布式系统和高性能计算等在内的多方面能力。只有少数足够幸运的人才有机会看到它的全貌。这也是为什么 AI 系统专家的待遇会更为优厚，因为这样的人才很难培养。</p><p>所以作为一个过来人，我想带你一起见识这一路的风景。我的成长过程中，接受过许多前辈的指点和帮助，现在，我也希望这些经验分享给你。</p><p>由于 AI 大模型是一个新兴的领域，大多数人几乎都在同一个起跑线上，所以即使你现在的工作与 AI 大模型并没有直接关系，或者你觉得，只需要学会使用它来完成日常工作就足够了，我还是建议你深入学习相关知识。因为对底层系统原理的掌握程度，是衡量工程师能力的重要标准。</p><h2 id="ai-系统很难-我能学会吗" tabindex="-1">AI 系统很难，我能学会吗？ <a class="header-anchor" href="#ai-系统很难-我能学会吗" aria-label="Permalink to &quot;AI 系统很难，我能学会吗？&quot;">​</a></h2><p>你可能会问，AI 系统很难，我能学会吗？当你觉得一件事难时，通常有两个原因，一个是看不见事物的全貌，另一个，则是看不透事物的本质。而这刚好是这门课能提供给你的。课程中，我将带你发现各项技术的本质和发展历史，把 AI 大模型系统必知必会的内容都囊括其中。</p><p>我会提炼 AI 系统在发展历程中最有价值的内容，为你精心规划一条循序渐进、稳扎稳打的学习道路，让你在欣赏旅途风景的同时，能够理解 AI 系统中最核心的设计思想，培养扎实的实战能力。</p><p>另外，我还会根据同学们的学习反馈，精选一些拓展学习资料，帮你强化学习效果。不过我还是想强调，学习的最佳模式还是兴趣导向、良性互动，这样的效果远远比被动接受要好得多。</p><h2 id="这门课程能让你获得什么呢" tabindex="-1">这门课程能让你获得什么呢？ <a class="header-anchor" href="#这门课程能让你获得什么呢" aria-label="Permalink to &quot;这门课程能让你获得什么呢？&quot;">​</a></h2><p>在开始介绍具体内容之前，我先来澄清一些大家常见的思维误区。目前，许多人都认为 AI 大模型系统是一种颠覆性的创新，然而从技术的角度来看并非如此。在过去的二十多年里，AI系统已经发展出了许多优秀的设计范式。正因如此，国内各大公司才能在短时间里实现文心一言和通义千问这类 ChatGPT 的平替。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><p>所以呢，在我们课程的设计当中，我将会优先讲解 AI 系统中最重要、最经受住时间考验的设计范式。这些范式，同样适用于计算机科学中最基础的设计哲学。通过学习这些知识，你将快速提升在 AI 领域的技术品味。</p><p>同时，你会发现，大模型技术的发展主要是为了实现从 AI 推荐内容，也就是 AIRC 到 AI 生成内容也就是 AIGC 的进化。那进一步呢，还实现了从结构化内容生成到“多模态”内容生成的变革。</p><p>因此，现在全球各大科技公司里，AI 大模型系统的核心研发人员，几乎都来自于 AI 推荐领域和多模态大模型领域。所以，我会结合技术的发展的规律，更科学地为你安排前置知识。</p><p>我在文稿里准备了一张知识地图，你可以打开看一看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" alt=""></a></p><p>接下来，我将结合目录的内容，和你聊一聊课程的安排，课程内容主要分为知识体系、技术原理、架构实战和前沿拓展四大部分。</p><p>首先是知识体系部分。</p><p>它包括了“热身篇”和“架构基础篇”这两篇内容。在这里，我将带你提升认知，夯实基础，搭建知识体系。</p><p>我会带你了解为什么 ChatGPT 是当之无愧的，下一代生态平台以及这一轮科技革命的最终目标是什么。同时，我还将带你少走弯路，在最短的时间内掌握主流的开源工具。你会发现，这些工具实际上很简单，只不过是在传播过程中被夸大、复杂化了。</p><p>同时，正如我前面所讲，AIGC 系统的诞生并非一朝一夕，它综合了过去二十年 AI 系统的发展经验。因此，我会先带你学习数据驱动的 AIRC 系统的相关知识，在学完这部分知识之后，你将具备参与 AIRC 系统开发的必要能力，为你后面学习 AIGC 系统打好基础。</p><p>第二部分是技术原理部分。</p><p>在这一部分，我将为你梳理目前 AI 大模型系统的发展脉络，解读关键技术背后的核心原理，带你跟上 AI 大模型理论的最新进展。</p><p>为了让你，更顺利地迈进，大模型相关的知识领域，我带你学习以下内容，比如：</p><ul><li><p>为什么大模型技术，起源于预训练模型。</p></li><li><p>为什么预训练模型，首先在视觉领域，得到广泛应用。</p></li><li><p>从预训练模型到大语言模型的发展历程。</p></li></ul><p>只有当你全面理解了技术原理，才能在架构和编码的过程中拥有坚实的后盾，避开研发过程中存在的一些缺陷和陷阱。</p><p>第三部分是架构实战。</p><p>在第三部分，我们将重点讨论工业级、AI 大模型系统的关键技术。我将带你学习，AIGC 系统存在的一些新问题以及我们的应对之道。</p><p>在学习的过程中，我将引导你结合前面学习的知识，给出你的解题思路，再让你对比我给出的“参考答案”。你会发现，掌握了 AI 系统的基础知识后，你完全有能力自己设计出 AI 大模型系统。</p><p>当然，我还会带你学习一些你可能暂时想不到的、新的设计理念和工程方法。比如，我将教你如何微调领域模型，甚至从零开始训练一个真实的大模型。你将更深入地理解，为何 OpenAI每次训练都需要花费上千万美元。</p><p>我们还会学习如何让你的系统，成为商业竞争中最有竞争力的智能体。这是让你的大模型应用走向自治的重要技能。这一章结束时，你将发现，你已经可以理解，全球最优秀的人工智能专家所做的技术方案，并开始与他们产生同频共振了。</p><p>第四部分是前沿拓展。</p><p>在最后的前沿拓展篇，我将带你开阔视野，为你的未来提供更多的可能。这部分，我们主要会探讨以下内容：</p><ul><li><p>在 AI 大模型快速发展的今天，有哪些机会可以提前布局？</p></li><li><p>在 AI 大模型的产业价值链中，有哪些机会是更适合你的？</p></li><li><p>AI 大模型未来的发展方向是什么？</p></li><li><p>我们应该如何，提前进行面试准备，调整职业规划？</p></li></ul><p>在完成所有的学习之后，你将全面提升，对 AI 大模型系统的认知，掌握核心研发能力。后面我准备了一张技能全景图，你可以点开查看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/3.jpeg" alt=""></a></p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>AI 大模型技术正在以惊人的速度发展，逐渐渗透到我们生活的方方面面。国内外的科技公司都在加紧构建属于自己的 AI 大模型平台和相应的应用生态。AI 大模型平台即将成为下一代应用平台，这件事已成为了各大科技公司的共识。我们身处其中，要做好长期投入的准备，一起来迎接下一轮行业洗牌时刻的到来。</p><p>无论你是互联网应用的开发者，还是平台型应用的建设者，此刻都是参与到新一轮技术革命中的最佳时间。希望你我在若干年后回看这段历史时，可以满意地面对自己的成长，而不是后悔再次因畏难或对新鲜事物的排斥，和潜在机会擦肩而过。</p><p>当然，学习 AI 大模型系统的过程并不轻松，但是，当你具备了这些能力后，将体会到难以言表的成就感。只有真正的热爱，才能让这漫长的学习过程变得有趣而充实。希望在这个浮躁的时代中，我们都能在技术带来的宁静，和快乐中不断成长。</p>',43)])])}const _=t(A,[["render",l]]);export{h as __pageData,_ as default};
